class TokenStream
  def initialize(tokens)
    @tokens = tokens
    @index = 0
    @peeked_value = nil
  end

  def next
    if @peeked_value
      @peeked_value = nil
      @result = @tokens[@index]
      @index += 1
      return @result
    else
      @index += 1
      return @tokens[@index - 1]
    end
  rescue IndexError
    raise StopIteration
  end

  def peek
    if @result.nil? && @tokens[@index].nil?
      raise StopIteration unless @index < @tokens.length
    end

    if @peeked_value.nil? && @index < @tokens.length
      @peeked_value = @tokens[@index]
    end

    raise StopIteration if @peeked_value.nil?
    @peeked_value
  end

  private

  def reset_peek!
    @peeked_value = nil
    @result = nil
  end
end
