class OpenRecord
  attr_accessor :_attributes, :_methods

  def initialize(**attrs)
    @attributes = {}
    @methods = Set.new

    attrs.each do |name, value|
      _set_attribute(name, value)
    end
  end

  def [](key)
    @attributes[key]
  end

  def []=(key, value)
    _set_attribute(key, value)
  end

  def respond_to?(method_name, including = false)
    # Check for getter methods
    if method_name.to_s.end_with?("=")
      # It's a setter method
      setter_name = method_name.to_s[0...-1]
      @methods.include?(setter_name) || @methods.include?(simple_setter_name(setter_name))
    else
      # It's a getter method
      @methods.include?(method_name)
    end
  end

  private

  def _set_attribute(name, value)
    @attributes[name] = value
    # Generate a method uniquely per instance to ensure idempotent method names
    instance_method_name = :"method_#{name}_self_id_#{@object_id}"
    @methods.add(instance_method_name)
    define_method(instance_method_name) do
      @attributes[name]
    end

    # Define the setter for this name
    define_method("#{instance_method_name}=") do |val|
      @attributes[name] = val
    end

    # Also define the getter using the standard name convention for Ruby's method handling
    # We need to make sure name and name= are both respond_to correctly
    @methods.add(name)
    define_method(name) do
      @attributes[name]
    end

    define_method("#{name}=") do |val|
      @attributes[name] = val
    end
  end

  def simple_setter_name(name)
    name.to_s.end_with?("=") ? name.to_s[0...-1] : name.to_s
  end
end
